window.__qzParts=window.__qzParts||{};window.__qzParts.khtn=[{"p":"Khoa học tự nhiên là môn học nghiên cứu về điều gì?","o":["Các sự vật, hiện tượng của thế giới tự nhiên và cách chúng vận động, biến đổi","Các con số và những phép tính trong toán học","Lịch sử các triều đại phong kiến xưa","Cách viết văn và làm thơ cho hay"],"a":"Các sự vật, hiện tượng của thế giới tự nhiên và cách chúng vận động, biến đổi","h":"Hãy chú ý đến chính tên gọi của môn học, nó gắn với thế giới xung quanh ta.","e":"Khoa học tự nhiên nghiên cứu các sự vật, hiện tượng trong tự nhiên như chất, năng lượng, vật sống và Trái Đất.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Để đo chiều dài của một quyển sách, em nên dùng dụng cụ nào sau đây?","o":["Cân đồng hồ","Thước (thước kẻ, thước mét)","Đồng hồ bấm giây","Nhiệt kế"],"a":"Thước (thước kẻ, thước mét)","h":"Chiều dài được đo bằng dụng cụ có chia vạch theo đơn vị độ dài.","e":"Thước dùng để đo độ dài; cân đo khối lượng, đồng hồ đo thời gian và nhiệt kế đo nhiệt độ.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong hệ đo lường quốc tế, đơn vị đo khối lượng chuẩn là gì?","o":["Mét (m)","Giây (s)","Kilôgam (kg)","Lít (l)"],"a":"Kilôgam (kg)","h":"Khối lượng của một vật cho biết lượng chất của vật đó.","e":"Kilôgam (kg) là đơn vị đo khối lượng chuẩn; mét đo độ dài, giây đo thời gian và lít đo thể tích.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Kính hiển vi được dùng để làm gì?","o":["Quan sát các ngôi sao ở rất xa","Đo nhiệt độ của một vật","Nghe những âm thanh rất nhỏ","Quan sát những vật rất nhỏ mà mắt thường không nhìn thấy được, như vi khuẩn hay tế bào"],"a":"Quan sát những vật rất nhỏ mà mắt thường không nhìn thấy được, như vi khuẩn hay tế bào","h":"Kính hiển vi giúp ta nhìn rõ những vật có kích thước vô cùng bé.","e":"Kính hiển vi phóng đại hình ảnh của các vật rất nhỏ như vi khuẩn, tế bào mà mắt thường không thấy được.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi làm việc trong phòng thực hành, việc làm nào sau đây KHÔNG được phép?","o":["Tự ý nếm hoặc ngửi trực tiếp hoá chất trong lọ","Đeo kính bảo hộ khi thầy cô yêu cầu","Rửa tay sạch sau khi thực hành","Làm thí nghiệm đúng theo hướng dẫn của thầy cô"],"a":"Tự ý nếm hoặc ngửi trực tiếp hoá chất trong lọ","h":"Hãy nghĩ đến những việc có thể gây nguy hiểm cho chính em.","e":"Hoá chất có thể độc hại nên tuyệt đối không nếm, không ngửi trực tiếp; cần tuân thủ các quy định an toàn trong phòng thực hành.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Chất thường tồn tại ở ba thể nào?","o":["Thể rắn, thể lỏng và ánh sáng","Thể rắn, thể lỏng và thể khí","Thể lỏng, thể khí và âm thanh","Thể rắn, thể khí và điện"],"a":"Thể rắn, thể lỏng và thể khí","h":"Hãy nhớ đến nước đá, nước lỏng và hơi nước quen thuộc.","e":"Mọi chất thường tồn tại ở ba thể: rắn, lỏng và khí, ví dụ nước đá, nước lỏng và hơi nước.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Chất ở thể rắn có đặc điểm nào sau đây?","o":["Có thể tích xác định nhưng không có hình dạng riêng","Không có hình dạng và thể tích xác định","Có hình dạng và thể tích xác định","Luôn chiếm đầy toàn bộ không gian chứa nó"],"a":"Có hình dạng và thể tích xác định","h":"Hãy hình dung một viên gạch hoặc một hòn đá đặt ở đâu cũng không đổi hình dạng.","e":"Chất ở thể rắn có hình dạng và thể tích xác định; thể lỏng chỉ có thể tích xác định, còn thể khí không có cả hai.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nước đá để ngoài trời nắng dần tan thành nước lỏng. Hiện tượng này gọi là gì?","o":["Sự đông đặc","Sự bay hơi","Sự ngưng tụ","Sự nóng chảy"],"a":"Sự nóng chảy","h":"Đây là quá trình chất chuyển từ thể rắn sang thể lỏng.","e":"Nóng chảy là quá trình chất chuyển từ thể rắn sang thể lỏng, như nước đá tan thành nước.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Quần áo ướt phơi ngoài nắng một lúc sẽ khô. Nước trong quần áo đã xảy ra hiện tượng gì?","o":["Bay hơi","Ngưng tụ","Đông đặc","Nóng chảy"],"a":"Bay hơi","h":"Nước lỏng đã biến đi đâu khi quần áo khô?","e":"Bay hơi là quá trình nước lỏng chuyển thành hơi nước, làm quần áo ướt dần khô đi.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vào sáng sớm, trên lá cây thường có những giọt nước nhỏ dù trời không mưa. Những giọt nước này hình thành do hơi nước trong không khí đã","o":["bay hơi thành hơi nước","ngưng tụ thành nước lỏng","đông đặc thành băng","nóng chảy thành nước"],"a":"ngưng tụ thành nước lỏng","h":"Hơi nước gặp lạnh sẽ biến thành giọt nước lỏng bám trên lá.","e":"Ngưng tụ là quá trình hơi nước chuyển thành nước lỏng; sương đọng trên lá cây vào sáng sớm là ví dụ quen thuộc.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Hiện tượng nào sau đây cho thấy tính chất hoá học của chất?","o":["Nước sôi ở 100 độ C","Thuỷ tinh trong suốt và dễ vỡ","Sắt để lâu trong không khí ẩm bị gỉ","Dây đồng dẫn điện tốt"],"a":"Sắt để lâu trong không khí ẩm bị gỉ","h":"Tính chất hoá học gắn với khả năng chất biến đổi thành chất khác.","e":"Sắt bị gỉ là sự biến đổi sắt thành chất mới nên thuộc tính chất hoá học; sôi, trong suốt, dẫn điện là tính chất vật lí.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Khí oxygen chiếm khoảng bao nhiêu phần trăm thể tích của không khí?","o":["Khoảng 1%","Khoảng 50%","Khoảng 78%","Khoảng 21%"],"a":"Khoảng 21%","h":"Khí chiếm nhiều nhất trong không khí là nitrogen, oxygen đứng thứ hai.","e":"Không khí gồm khoảng 78% nitrogen, khoảng 21% oxygen và khoảng 1% các khí khác.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khí oxygen rất cần thiết cho đời sống vì nó","o":["duy trì sự cháy và cần cho hô hấp của người, động vật","giúp nước đóng băng nhanh hơn","giúp mọi cây cối ra hoa cùng lúc","làm cho kim loại cứng hơn"],"a":"duy trì sự cháy và cần cho hô hấp của người, động vật","h":"Hãy nhớ ngọn nến sẽ tắt khi bị đậy kín và con người cần hít thở liên tục.","e":"Oxygen duy trì sự cháy và là khí cần thiết cho hô hấp của người và động vật.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Có một hỗn hợp gồm bột sắt trộn lẫn với cát. Cách tách bột sắt ra khỏi cát đơn giản nhất là","o":["lọc hỗn hợp bằng giấy lọc","dùng nam châm đưa lại gần để hút bột sắt","đun nóng cho hỗn hợp bay hơi hết","đổ bỏ phần trên mặt của hỗn hợp"],"a":"dùng nam châm đưa lại gần để hút bột sắt","h":"Hãy nhớ tính chất đặc biệt của sắt khi gặp nam châm.","e":"Nam châm hút được sắt nên dùng nam châm là cách đơn giản và hiệu quả nhất để tách bột sắt khỏi cát.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Lốp xe thường được làm bằng cao su vì cao su có tính chất nổi bật nào?","o":["Dẫn điện rất tốt","Trong suốt như thuỷ tinh","Đàn hồi tốt, ma sát lớn và không thấm nước","Nhẹ hơn không khí"],"a":"Đàn hồi tốt, ma sát lớn và không thấm nước","h":"Lốp xe cần bám đường tốt và chịu được biến dạng khi xe chạy.","e":"Cao su đàn hồi, có ma sát lớn giúp xe bám đường và không thấm nước nên được dùng làm lốp xe, ủng đi mưa.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Lực là gì?","o":["Một dạng năng lượng chứa trong vật","Khả năng chạy nhanh của một vật","Sự chuyển động của một vật","Tác dụng đẩy hoặc kéo của vật này lên vật khác"],"a":"Tác dụng đẩy hoặc kéo của vật này lên vật khác","h":"Khi em đẩy xe hay kéo ngăn bàn, em đang tác dụng điều gì lên vật?","e":"Lực là tác dụng đẩy hoặc kéo của vật này lên vật khác, ví dụ tay đẩy xe, tay kéo dây.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trường hợp nào sau đây là lực không tiếp xúc?","o":["Nam châm hút chiếc đinh sắt dù chưa chạm vào đinh","Tay đẩy chiếc xe đạp","Chân đá quả bóng","Hai bạn kéo co bằng dây"],"a":"Nam châm hút chiếc đinh sắt dù chưa chạm vào đinh","h":"Lực không tiếp xúc xảy ra khi vật tác dụng lực mà không chạm vào vật kia.","e":"Nam châm hút đinh sắt từ xa nên đó là lực không tiếp xúc; các trường hợp còn lại đều có sự chạm trực tiếp.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trọng lực là gì?","o":["Lực đẩy của nước tác dụng lên vật","Lực hút của Trái Đất tác dụng lên mọi vật","Lực hút giữa hai cực của nam châm","Lực thổi của gió lên mọi vật"],"a":"Lực hút của Trái Đất tác dụng lên mọi vật","h":"Nhờ lực này mà mọi vật rơi xuống đều hướng về mặt đất.","e":"Trọng lực là lực hút của Trái Đất tác dụng lên mọi vật, kéo mọi vật về phía mặt đất.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Lực tác dụng lên một vật có thể gây ra kết quả nào?","o":["Chỉ làm vật nóng lên","Chỉ làm vật đổi màu","Làm vật thay đổi chuyển động hoặc biến dạng, hoặc cả hai","Làm vật biến mất hoàn toàn"],"a":"Làm vật thay đổi chuyển động hoặc biến dạng, hoặc cả hai","h":"Hãy nghĩ khi em đá bóng đứng yên và khi em bóp một quả bóng cao su.","e":"Lực có thể làm vật đang đứng yên chuyển động, chuyển động nhanh hay chậm lại, hoặc làm vật biến dạng.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Trường hợp nào sau đây lực ma sát có ích?","o":["Ma sát làm đế giày bị mòn dần","Ma sát làm các chi tiết máy bị mòn và nóng lên","Ma sát làm xích xe đạp bị mòn","Ma sát giữa lốp xe và mặt đường giúp xe bám đường, không bị trượt"],"a":"Ma sát giữa lốp xe và mặt đường giúp xe bám đường, không bị trượt","h":"Ma sát có ích khi nó giúp chuyển động được an toàn và thuận lợi.","e":"Ma sát giữa lốp xe và mặt đường giúp xe bám đường; còn ma sát làm mòn vật là ma sát có hại.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trường hợp nào sau đây lực ma sát có hại?","o":["Ma sát giữa các bộ phận chuyển động trong máy làm chúng bị mòn và nóng lên","Ma sát giữa tay và cán vợt giúp cầm chắc vợt","Ma sát giữa đế giày và mặt đường giúp ta đi không trượt","Ma sát giữa phấn và bảng giúp viết được chữ"],"a":"Ma sát giữa các bộ phận chuyển động trong máy làm chúng bị mòn và nóng lên","h":"Ma sát có hại khi nó gây mòn, nóng và cản trở hoạt động của máy móc.","e":"Ma sát giữa các chi tiết máy làm chúng mòn và nóng lên nên người ta phải tra dầu mỡ để giảm ma sát có hại này.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Khi ta kéo giãn một lò xo rồi buông tay ra, lò xo trở lại hình dạng ban đầu nhờ có","o":["lực ma sát","lực đàn hồi","trọng lực","lực hút của nam châm"],"a":"lực đàn hồi","h":"Đây là loại lực xuất hiện khi vật bị biến dạng như lò xo, dây cao su.","e":"Khi lò xo bị kéo giãn hoặc nén, nó sinh ra lực đàn hồi kéo lò xo trở về hình dạng ban đầu.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vật nào sau đây phát ra năng lượng ánh sáng?","o":["Cục pin chưa sử dụng","Ấm nước vừa đun sôi","Bóng đèn đang sáng","Quyển sách để trên bàn"],"a":"Bóng đèn đang sáng","h":"Năng lượng ánh sáng còn gọi là quang năng, giúp ta nhìn thấy vật.","e":"Bóng đèn đang sáng phát ra năng lượng ánh sáng; pin chứa hoá năng, ấm nước nóng chứa nhiệt năng.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vật nào sau đây có động năng?","o":["Chiếc xe đạp dựng yên trong sân","Quyển sách nằm yên trên bàn","Hòn đá nằm yên trên mặt đất","Chiếc xe đạp đang chạy trên đường"],"a":"Chiếc xe đạp đang chạy trên đường","h":"Động năng là năng lượng của vật đang chuyển động.","e":"Vật đang chuyển động thì có động năng, như xe đạp đang chạy; các vật đứng yên không có động năng.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi quạt điện hoạt động, năng lượng điện đã chuyển hoá chủ yếu thành dạng năng lượng nào?","o":["Động năng của cánh quạt (kèm một phần nhiệt năng)","Quang năng","Hoá năng","Âm năng"],"a":"Động năng của cánh quạt (kèm một phần nhiệt năng)","h":"Cánh quạt quay được là nhờ dạng năng lượng nào?","e":"Quạt điện biến điện năng thành động năng làm cánh quạt quay, đồng thời một phần nhỏ thành nhiệt năng.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Đèn pin đang sáng dùng pin. Sự chuyển hoá năng lượng trong đèn pin là","o":["động năng chuyển thành điện năng","hoá năng của pin chuyển thành quang năng","quang năng chuyển thành hoá năng","nhiệt năng chuyển thành động năng"],"a":"hoá năng của pin chuyển thành quang năng","h":"Hãy bắt đầu từ nguồn năng lượng dự trữ trong pin.","e":"Pin chứa hoá năng; khi đèn pin sáng, hoá năng của pin chuyển hoá thành năng lượng ánh sáng.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Việc làm nào sau đây giúp tiết kiệm năng lượng?","o":["Bật thật nhiều đèn cho phòng thật sáng","Mở cửa tủ lạnh thật lâu để ngắm đồ ăn","Tắt đèn và quạt khi ra khỏi phòng","Để ti vi chạy suốt ngày dù không ai xem"],"a":"Tắt đèn và quạt khi ra khỏi phòng","h":"Tiết kiệm năng lượng là chỉ dùng năng lượng khi thật cần thiết.","e":"Tắt các thiết bị điện khi không sử dụng giúp tiết kiệm điện năng và bảo vệ môi trường.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Đơn vị cấu tạo cơ bản của mọi cơ thể sống là gì?","o":["Mô","Cơ quan","Hệ cơ quan","Tế bào"],"a":"Tế bào","h":"Cơ thể của em được xây nên từ hàng tỉ đơn vị rất nhỏ.","e":"Tế bào là đơn vị cấu tạo cơ bản của mọi cơ thể sống, từ vi khuẩn đến con người.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Tế bào thực vật khác tế bào động vật ở điểm nào?","o":["Có thành tế bào và lục lạp","Có nhân tế bào","Có màng tế bào","Có chất tế bào"],"a":"Có thành tế bào và lục lạp","h":"Hãy nhớ bộ phận giúp lá cây quang hợp và lớp vỏ cứng bao ngoài tế bào lá.","e":"Tế bào thực vật có thành tế bào và lục lạp để quang hợp, còn tế bào động vật không có hai bộ phận này.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Lục lạp trong tế bào thực vật có vai trò gì?","o":["Giúp cây hô hấp vào ban đêm","Hấp thụ ánh sáng Mặt Trời để cây quang hợp, tạo chất dinh dưỡng","Bảo vệ tế bào khỏi vi khuẩn","Giúp rễ cây hút nước"],"a":"Hấp thụ ánh sáng Mặt Trời để cây quang hợp, tạo chất dinh dưỡng","h":"Lục lạp chứa chất diệp lục làm lá có màu xanh.","e":"Lục lạp chứa diệp lục, hấp thụ ánh sáng để quang hợp, tạo chất dinh dưỡng nuôi cây.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Sinh vật nào sau đây là cơ thể đơn bào?","o":["Con cá vàng","Cây ngô","Trùng roi","Con mèo"],"a":"Trùng roi","h":"Cơ thể đơn bào chỉ gồm đúng một tế bào duy nhất.","e":"Trùng roi, amip là cơ thể đơn bào; cá, cây ngô và mèo là cơ thể đa bào gồm rất nhiều tế bào.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Thứ tự đúng của các cấp độ tổ chức trong cơ thể đa bào từ nhỏ đến lớn là","o":["Mô tạo thành tế bào, tế bào tạo thành cơ quan, cơ quan tạo thành cơ thể","Cơ quan tạo thành mô, mô tạo thành tế bào, tế bào tạo thành cơ thể","Tế bào tạo thành cơ quan, cơ quan tạo thành mô, mô tạo thành cơ thể","Tế bào tạo thành mô, mô tạo thành cơ quan, cơ quan tạo thành hệ cơ quan, hệ cơ quan tạo thành cơ thể"],"a":"Tế bào tạo thành mô, mô tạo thành cơ quan, cơ quan tạo thành hệ cơ quan, hệ cơ quan tạo thành cơ thể","h":"Hãy bắt đầu từ đơn vị nhỏ nhất là tế bào và xếp dần lên.","e":"Các cấp độ tổ chức trong cơ thể đa bào đi từ tế bào lên mô, cơ quan, hệ cơ quan rồi đến cơ thể hoàn chỉnh.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Nhiều cơ quan cùng phối hợp thực hiện một chức năng sống thì tạo thành","o":["hệ cơ quan","mô","tế bào","cơ thể đơn bào"],"a":"hệ cơ quan","h":"Ví dụ tim và các mạch máu cùng làm nhiệm vụ vận chuyển máu.","e":"Tập hợp các cơ quan cùng phối hợp thực hiện một chức năng sống gọi là hệ cơ quan, như hệ tuần hoàn gồm tim và mạch máu.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhận định nào đúng về vi khuẩn?","o":["Vi khuẩn chưa có cấu tạo tế bào","Vi khuẩn là sinh vật có cấu tạo tế bào, kích thước rất nhỏ, phải dùng kính hiển vi mới thấy","Vi khuẩn nhìn thấy rõ bằng mắt thường","Tất cả vi khuẩn đều gây bệnh cho người"],"a":"Vi khuẩn là sinh vật có cấu tạo tế bào, kích thước rất nhỏ, phải dùng kính hiển vi mới thấy","h":"Vi khuẩn nhỏ đến mức cần dụng cụ phóng đại mới quan sát được.","e":"Vi khuẩn là sinh vật có cấu tạo tế bào và kích thước rất nhỏ; có vi khuẩn có hại nhưng cũng có nhiều vi khuẩn có ích.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Virus khác vi khuẩn ở điểm cơ bản nào?","o":["Virus luôn lớn hơn vi khuẩn","Virus tự di chuyển được như động vật","Virus chưa có cấu tạo tế bào hoàn chỉnh, còn vi khuẩn là sinh vật có tế bào","Virus là sinh vật đa bào"],"a":"Virus chưa có cấu tạo tế bào hoàn chỉnh, còn vi khuẩn là sinh vật có tế bào","h":"Đây là lí do virus không được coi là sinh vật có cấu tạo tế bào.","e":"Vi khuẩn là sinh vật đơn bào, còn virus chưa có cấu tạo tế bào hoàn chỉnh và chỉ nhân lên được khi ở trong tế bào của vật chủ.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Con người đã lợi dụng vi khuẩn có ích để làm việc nào sau đây?","o":["Gây bệnh tả cho người","Làm thức ăn bị ôi thiu","Gây sâu răng cho trẻ em","Lên men làm sữa chua, muối dưa, muối cà"],"a":"Lên men làm sữa chua, muối dưa, muối cà","h":"Hãy nhớ món sữa chua em vẫn ăn hằng ngày.","e":"Nhiều vi khuẩn có ích được dùng để lên men làm sữa chua, muối dưa cà; một số vi khuẩn khác mới gây bệnh.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Tính từ Mặt Trời ra xa, Trái Đất là hành tinh thứ mấy trong Hệ Mặt Trời?","o":["Hành tinh thứ ba","Hành tinh thứ nhất","Hành tinh thứ hai","Hành tinh thứ năm"],"a":"Hành tinh thứ ba","h":"Trước Trái Đất là Thuỷ tinh và Kim tinh.","e":"Thứ tự từ Mặt Trời là: Thuỷ tinh, Kim tinh, Trái Đất..., nên Trái Đất là hành tinh thứ ba trong Hệ Mặt Trời.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Hiện tượng ngày và đêm trên Trái Đất là do","o":["Mặt Trăng quay quanh Trái Đất","Trái Đất tự quay quanh trục của nó","Trái Đất chuyển động quanh Mặt Trời","Mặt Trời quay quanh Trái Đất"],"a":"Trái Đất tự quay quanh trục của nó","h":"Khi một nửa Trái Đất hướng về Mặt Trời thì nửa kia chìm trong bóng tối.","e":"Trái Đất tự quay quanh trục nên nơi được Mặt Trời chiếu sáng là ban ngày, nơi khuất sáng là ban đêm.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trái Đất chuyển động quanh Mặt Trời gây ra hiện tượng nào?","o":["Ngày và đêm","Mặt Trăng tròn và khuyết","Các mùa trong năm","Thuỷ triều lên xuống"],"a":"Các mùa trong năm","h":"Hành trình một vòng quanh Mặt Trời của Trái Đất kéo dài một năm.","e":"Trái Đất chuyển động quanh Mặt Trời kết hợp với trục quay nghiêng gây ra các mùa xuân, hạ, thu, đông trong năm.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Mặt Trăng là vệ tinh tự nhiên của Trái Đất. Mặt Trăng sáng được là do","o":["nó tự phát sáng như Mặt Trời","nó được thắp sáng bằng điện","nó phản chiếu ánh sáng của các ngôi sao","nó phản chiếu ánh sáng của Mặt Trời"],"a":"nó phản chiếu ánh sáng của Mặt Trời","h":"Bản thân Mặt Trăng không phải là một nguồn sáng.","e":"Mặt Trăng không tự phát sáng mà phản chiếu ánh sáng Mặt Trời chiếu tới nên ta thấy nó sáng trên bầu trời đêm.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nguyên tử gồm hai phần chính là:","o":["Hạt nhân nằm ở trung tâm và các electron chuyển động xung quanh hạt nhân","Hạt nhân và các phân tử nước","Các proton chuyển động xung quanh một electron nằm ở trung tâm","Chỉ gồm các electron xếp thành từng lớp"],"a":"Hạt nhân nằm ở trung tâm và các electron chuyển động xung quanh hạt nhân","h":"Hãy nhớ mô hình cấu tạo nguyên tử đã học.","e":"Nguyên tử gồm hạt nhân mang điện tích dương ở trung tâm và các electron mang điện tích âm chuyển động xung quanh hạt nhân.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hạt nhân nguyên tử được cấu tạo từ các hạt nào?","o":["Proton và electron","Proton và neutron","Electron và neutron","Chỉ gồm các electron"],"a":"Proton và neutron","h":"Hạt nhân là phần nằm ở trung tâm của nguyên tử.","e":"Hạt nhân nguyên tử gồm hai loại hạt là proton (mang điện tích dương) và neutron (không mang điện tích); electron chuyển động ở xung quanh hạt nhân.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hạt proton trong hạt nhân nguyên tử mang điện tích:","o":["Điện tích âm","Không mang điện tích","Điện tích dương","Vừa mang điện tích dương vừa mang điện tích âm"],"a":"Điện tích dương","h":"Proton là hạt viết tắt là p, nằm trong hạt nhân.","e":"Proton mang điện tích dương (+1), electron mang điện tích âm (-1), còn neutron không mang điện tích.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hạt electron trong nguyên tử mang điện tích:","o":["Điện tích dương","Không mang điện tích","Lúc dương lúc âm tuỳ theo vị trí","Điện tích âm"],"a":"Điện tích âm","h":"Electron là hạt rất nhẹ, chuyển động xung quanh hạt nhân.","e":"Electron mang điện tích âm (-1). Vì số proton bằng số electron nên nguyên tử trung hoà về điện.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hạt neutron trong hạt nhân nguyên tử có đặc điểm là:","o":["Không mang điện tích","Mang điện tích dương","Mang điện tích âm","Mang điện tích dương gấp đôi proton"],"a":"Không mang điện tích","h":"Tên gọi neutron gợi ý về tính trung hoà điện.","e":"Neutron là hạt không mang điện tích, cùng với proton tạo nên hạt nhân nguyên tử.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nguyên tố hoá học là:","o":["Tập hợp các nguyên tử có cùng số neutron trong hạt nhân","Tập hợp các nguyên tử có cùng số proton trong hạt nhân","Tập hợp các phân tử giống hệt nhau về khối lượng","Một chất bất kì được tạo thành từ hai nguyên tố trở lên"],"a":"Tập hợp các nguyên tử có cùng số proton trong hạt nhân","h":"Hãy chú ý đến đại lượng quyết định một nguyên tử thuộc nguyên tố nào.","e":"Nguyên tố hoá học là tập hợp các nguyên tử có cùng số proton trong hạt nhân; số proton là đặc trưng của một nguyên tố.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Kí hiệu hoá học của nguyên tố sắt là:","o":["Ir","S","Fe","F"],"a":"Fe","h":"Kí hiệu này bắt nguồn từ tên Latin của sắt là Ferrum.","e":"Sắt có kí hiệu hoá học là Fe (từ tiếng Latin Ferrum); S là lưu huỳnh, F là flo (fluorine).","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Kí hiệu hoá học Al dùng để chỉ nguyên tố nào?","o":["Bạc","Vàng","Sắt","Nhôm"],"a":"Nhôm","h":"Đây là kim loại nhẹ, thường dùng làm nồi, chảo và vỏ máy bay.","e":"Al là kí hiệu của nguyên tố nhôm (aluminium); bạc là Ag, vàng là Au, sắt là Fe.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Phân tử là:","o":["Hạt gồm một số nguyên tử liên kết với nhau, đại diện cho chất và mang đầy đủ tính chất hoá học của chất đó","Hạt nhỏ nhất cấu tạo nên hạt nhân nguyên tử","Một loại hạt mang điện tích dương trong nguyên tử","Tập hợp nhiều chất khác nhau trộn lẫn vào nhau"],"a":"Hạt gồm một số nguyên tử liên kết với nhau, đại diện cho chất và mang đầy đủ tính chất hoá học của chất đó","h":"Ví dụ: một phân tử nước gồm các nguyên tử hydrogen và oxygen liên kết với nhau.","e":"Phân tử là hạt đại diện cho chất, được tạo thành từ một số nguyên tử liên kết với nhau và mang đầy đủ tính chất hoá học của chất.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Chất nào sau đây là đơn chất?","o":["Nước (H2O)","Khí oxygen (O2)","Khí carbon dioxide (CO2)","Muối ăn (NaCl)"],"a":"Khí oxygen (O2)","h":"Hãy đếm số nguyên tố tạo thành mỗi chất.","e":"Đơn chất là chất tạo thành từ một nguyên tố hoá học; O2 chỉ do nguyên tố oxygen tạo nên, còn H2O, CO2, NaCl đều do từ hai nguyên tố trở lên tạo thành nên là hợp chất.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Chất nào sau đây là hợp chất?","o":["Kim loại đồng (Cu)","Khí nitrogen (N2)","Nước (H2O)","Khí hydrogen (H2)"],"a":"Nước (H2O)","h":"Hợp chất phải do từ hai nguyên tố hoá học trở lên tạo thành.","e":"Hợp chất là chất tạo thành từ hai nguyên tố hoá học trở lên; nước H2O do hydrogen và oxygen tạo thành, còn Cu, N2, H2 đều là đơn chất.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Hoá trị của một nguyên tố hoá học là:","o":["Khối lượng của một nguyên tử tính bằng đơn vị amu","Tổng số electron có trong một nguyên tử","Số thứ tự của nguyên tố trong bảng tuần hoàn","Con số biểu thị khả năng liên kết của nguyên tử nguyên tố đó với nguyên tử của nguyên tố khác"],"a":"Con số biểu thị khả năng liên kết của nguyên tử nguyên tố đó với nguyên tử của nguyên tố khác","h":"Hoá trị cho biết một nguyên tử có thể liên kết với bao nhiêu nguyên tử khác.","e":"Hoá trị là con số biểu thị khả năng liên kết của nguyên tử nguyên tố này với nguyên tử nguyên tố khác, thường được biểu diễn bằng chữ số La Mã.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Công thức hoá học H2O cho biết một phân tử nước được tạo thành từ:","o":["2 nguyên tử hydrogen và 1 nguyên tử oxygen","1 nguyên tử hydrogen và 2 nguyên tử oxygen","2 phân tử hydrogen và 1 phân tử oxygen","1 nguyên tử hydrogen và 1 nguyên tử oxygen"],"a":"2 nguyên tử hydrogen và 1 nguyên tử oxygen","h":"Chỉ số nhỏ ở dưới chân mỗi kí hiệu cho biết số nguyên tử của nguyên tố đó.","e":"Trong công thức H2O, chỉ số 2 ở dưới chân H cho biết có 2 nguyên tử hydrogen, còn O không có chỉ số nghĩa là có 1 nguyên tử oxygen.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Biết khối lượng nguyên tử của hydrogen là 1 amu và của oxygen là 16 amu. Khối lượng phân tử của nước (H2O) bằng:","o":["17 amu","18 amu","32 amu","34 amu"],"a":"18 amu","h":"Hãy cộng khối lượng của tất cả các nguyên tử có trong một phân tử nước.","e":"Phân tử H2O gồm 2 nguyên tử H và 1 nguyên tử O nên khối lượng phân tử bằng 2 × 1 + 16 = 18 amu.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Tốc độ của một chuyển động được tính bằng công thức nào?","o":["v = s × t","v = t/s","v = s/t","v = s − t"],"a":"v = s/t","h":"Tốc độ cho biết quãng đường đi được trong một đơn vị thời gian.","e":"Tốc độ bằng quãng đường đi được chia cho thời gian đi hết quãng đường đó: v = s/t.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong thực tế, tốc độ thường được đo bằng các đơn vị nào?","o":["Mét (m) và kilômét (km)","Giây (s) và giờ (h)","Kilôgam (kg) và tấn (t)","Mét trên giây (m/s) và kilômét trên giờ (km/h)"],"a":"Mét trên giây (m/s) và kilômét trên giờ (km/h)","h":"Đơn vị tốc độ phải gồm đơn vị quãng đường chia cho đơn vị thời gian.","e":"Đơn vị tốc độ thường dùng là m/s và km/h; m, km là đơn vị quãng đường còn s, h là đơn vị thời gian.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Một bạn học sinh chạy quãng đường 100 m trong thời gian 20 s. Tốc độ của bạn học sinh đó là:","o":["5 m/s","20 m/s","0,5 m/s","2000 m/s"],"a":"5 m/s","h":"Hãy áp dụng công thức v = s/t.","e":"Tốc độ của bạn học sinh là v = s/t = 100/20 = 5 m/s.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Âm thanh được phát ra khi nào?","o":["Khi một vật đứng yên hoàn toàn","Khi một vật dao động","Khi một vật bị nung nóng","Khi một vật bị chiếu sáng"],"a":"Khi một vật dao động","h":"Hãy nghĩ đến dây đàn khi được gảy.","e":"Mọi âm thanh đều do vật dao động phát ra; dao động càng mạnh, âm phát ra càng to.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Âm thanh có thể truyền qua được các môi trường nào?","o":["Chỉ chất khí","Chỉ chất rắn và chất lỏng","Chất rắn, chất lỏng và chất khí","Chất rắn, chất lỏng, chất khí và cả chân không"],"a":"Chất rắn, chất lỏng và chất khí","h":"Ta nghe được tiếng gõ cửa qua cánh cửa gỗ và nghe cá heo gọi nhau dưới nước.","e":"Âm thanh truyền qua được chất rắn, chất lỏng và chất khí, nhưng không truyền được qua chân không vì ở đó không có vật chất.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hai nhà du hành vũ trụ làm việc ngoài không gian không thể trò chuyện trực tiếp với nhau mà phải dùng máy bộ đàm. Nguyên nhân là:","o":["Âm thanh truyền qua chân không quá chậm nên không nghe kịp","Tiếng nói bị trọng lực của Trái Đất kéo ngược trở lại","Âm thanh chỉ truyền được trong không khí giàu oxygen","Âm thanh không truyền được qua chân không vì không có môi trường vật chất để truyền dao động"],"a":"Âm thanh không truyền được qua chân không vì không có môi trường vật chất để truyền dao động","h":"Ngoài không gian vũ trụ gần như không có vật chất.","e":"Âm thanh cần môi trường vật chất (rắn, lỏng, khí) để truyền dao động; ngoài không gian là chân không nên tiếng nói không truyền đi được.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Độ to của âm thanh phụ thuộc vào yếu tố nào của dao động?","o":["Biên độ dao động","Tần số dao động","Tốc độ truyền âm","Khoảng cách từ nguồn âm đến tai"],"a":"Biên độ dao động","h":"Gảy dây đàn mạnh tay thì dây dao động thế nào và âm nghe ra sao?","e":"Biên độ dao động càng lớn thì âm phát ra càng to; biên độ dao động càng nhỏ thì âm phát ra càng nhỏ.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Độ cao của âm thanh phụ thuộc vào yếu tố nào?","o":["Biên độ dao động: biên độ càng lớn, âm càng cao","Tần số dao động: tần số càng lớn, âm phát ra càng cao","Kích thước của nguồn âm: nguồn âm càng to, âm càng cao","Môi trường truyền âm: truyền qua chất rắn âm cao hơn qua chất khí"],"a":"Tần số dao động: tần số càng lớn, âm phát ra càng cao","h":"Âm cao hay thấp gắn liền với số dao động trong một giây.","e":"Tần số dao động càng lớn thì âm phát ra càng cao (càng bổng); tần số càng nhỏ thì âm phát ra càng thấp (càng trầm).","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong một môi trường trong suốt và đồng tính, ánh sáng truyền đi theo:","o":["Đường cong","Đường gấp khúc","Đường thẳng","Đường tròn"],"a":"Đường thẳng","h":"Hãy quan sát tia nắng xuyên qua khe cửa hẹp.","e":"Ánh sáng truyền đi theo đường thẳng trong môi trường trong suốt và đồng tính; đây là định luật truyền thẳng của ánh sáng.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Ảnh của một vật tạo bởi gương phẳng có đặc điểm nào sau đây?","o":["Là ảnh thật, hứng được trên màn chắn và bằng vật","Là ảnh ảo, luôn nhỏ hơn vật","Là ảnh ảo, luôn lớn hơn vật","Là ảnh ảo, có kích thước bằng vật"],"a":"Là ảnh ảo, có kích thước bằng vật","h":"Hãy nhớ lại thí nghiệm dùng tấm kính trong và hai cây nến giống nhau.","e":"Ảnh tạo bởi gương phẳng là ảnh ảo (không hứng được trên màn), có kích thước bằng vật và đối xứng với vật qua mặt gương.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Một thanh nam châm có hai cực là cực Bắc (kí hiệu N) và cực Nam (kí hiệu S). Khi đưa cực Bắc của thanh nam châm này lại gần cực Bắc của một thanh nam châm khác, hiện tượng xảy ra là:","o":["Hai nam châm đẩy nhau","Hai nam châm hút nhau","Không xảy ra hiện tượng gì","Cả hai nam châm mất hết từ tính"],"a":"Hai nam châm đẩy nhau","h":"Hãy nhớ quy tắc: cùng cực thì..., khác cực thì...","e":"Hai cực cùng tên của nam châm thì đẩy nhau, hai cực khác tên thì hút nhau; ở đây cả hai đều là cực Bắc nên chúng đẩy nhau.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"La bàn giúp ta xác định được phương hướng là nhờ:","o":["Kim la bàn luôn chỉ về phía Mặt Trời mọc","Kim la bàn là một nam châm nhỏ, luôn tự định hướng theo hướng Bắc – Nam dưới tác dụng của từ trường Trái Đất","Trong la bàn có một động cơ nhỏ làm kim quay về hướng Bắc","Kim la bàn chỉ về nơi có nhiều ánh sáng nhất"],"a":"Kim la bàn là một nam châm nhỏ, luôn tự định hướng theo hướng Bắc – Nam dưới tác dụng của từ trường Trái Đất","h":"Hãy liên hệ tính chất của nam châm với việc kim la bàn tự quay khi để tự do.","e":"Kim la bàn là một nam châm nhỏ được đặt tự do nên dưới tác dụng của từ trường Trái Đất, nó luôn định hướng sao cho một đầu chỉ hướng Bắc, một đầu chỉ hướng Nam.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Trao đổi chất ở sinh vật là quá trình:","o":["Cơ thể sinh vật tăng lên về kích thước và khối lượng","Sinh vật tạo ra các cá thể mới giống mình","Cơ thể lấy các chất cần thiết từ môi trường vào và thải các chất cặn bã ra môi trường","Lá cây tổng hợp chất hữu cơ từ nước và khí carbon dioxide"],"a":"Cơ thể lấy các chất cần thiết từ môi trường vào và thải các chất cặn bã ra môi trường","h":"Hãy nghĩ đến việc cơ thể hằng ngày ăn, uống và thải chất thừa ra ngoài.","e":"Trao đổi chất là quá trình cơ thể sinh vật lấy các chất cần thiết từ môi trường (thức ăn, nước, oxygen...) và thải các chất cặn bã ra môi trường.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Quang hợp là quá trình diễn ra chủ yếu ở lá cây, trong đó:","o":["Cây phân giải chất hữu cơ để lấy năng lượng cho hoạt động sống","Cây hấp thụ khí oxygen và thải ra khí carbon dioxide","Cây hút muối khoáng từ đất để tạo ra hạt giống","Cây sử dụng nước, khí carbon dioxide và năng lượng ánh sáng để tổng hợp chất hữu cơ, đồng thời giải phóng khí oxygen"],"a":"Cây sử dụng nước, khí carbon dioxide và năng lượng ánh sáng để tổng hợp chất hữu cơ, đồng thời giải phóng khí oxygen","h":"Đây là quá trình giúp cây tự chế tạo thức ăn cho mình.","e":"Quang hợp là quá trình lá cây dùng nước, khí carbon dioxide và năng lượng ánh sáng mặt trời để tổng hợp chất hữu cơ và giải phóng khí oxygen.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khí được cây xanh giải phóng ra môi trường trong quá trình quang hợp là:","o":["Khí oxygen (O2)","Khí carbon dioxide (CO2)","Khí nitrogen (N2)","Khí hydrogen (H2)"],"a":"Khí oxygen (O2)","h":"Đây là khí cần cho sự hô hấp của người và động vật.","e":"Trong quang hợp, cây hấp thụ khí carbon dioxide và giải phóng khí oxygen; nhờ đó cây xanh giúp bổ sung oxygen cho không khí.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Yếu tố nào sau đây không ảnh hưởng trực tiếp đến quá trình quang hợp của cây?","o":["Cường độ ánh sáng chiếu vào cây","Âm thanh từ môi trường xung quanh","Lượng nước cây được cung cấp","Nồng độ khí carbon dioxide trong không khí"],"a":"Âm thanh từ môi trường xung quanh","h":"Hãy liệt kê các nguyên liệu và điều kiện mà quang hợp cần.","e":"Quang hợp cần ánh sáng, nước và khí carbon dioxide nên các yếu tố này ảnh hưởng trực tiếp đến quang hợp; âm thanh không tham gia vào quá trình quang hợp.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Hô hấp tế bào là quá trình tế bào:","o":["Tổng hợp chất hữu cơ từ nước và khí carbon dioxide nhờ ánh sáng","Tạo ra khí oxygen và giải phóng ra ngoài cơ thể","Phân giải chất hữu cơ với sự tham gia của khí oxygen để giải phóng năng lượng cần cho các hoạt động sống","Vận chuyển khí oxygen từ phổi đi khắp cơ thể"],"a":"Phân giải chất hữu cơ với sự tham gia của khí oxygen để giải phóng năng lượng cần cho các hoạt động sống","h":"Đây là quá trình cung cấp năng lượng cho mọi hoạt động của tế bào.","e":"Hô hấp tế bào phân giải chất hữu cơ (với sự tham gia của oxygen) thành carbon dioxide và nước, đồng thời giải phóng năng lượng cho các hoạt động sống.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Một chậu cây đặt gần cửa sổ, sau vài ngày ngọn cây cong và mọc hướng về phía có ánh sáng. Hiện tượng này thể hiện khả năng nào của cây?","o":["Di chuyển từ nơi tối sang nơi sáng","Sinh sản để tạo ra cây con","Thải các chất cặn bã ra ngoài","Cảm ứng — phản ứng lại kích thích ánh sáng từ môi trường"],"a":"Cảm ứng — phản ứng lại kích thích ánh sáng từ môi trường","h":"Sinh vật có một tính chất là phản ứng lại các tác động của môi trường.","e":"Cây mọc hướng về phía ánh sáng là phản ứng cảm ứng của cây đối với kích thích ánh sáng; cảm ứng là khả năng sinh vật phản ứng lại các kích thích từ môi trường.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi chạm nhẹ vào lá cây xấu hổ (cây trinh nữ), các lá chét lập tức khép lại. Đây là biểu hiện của tính chất nào của sinh vật?","o":["Cảm ứng với kích thích","Sinh trưởng","Sinh sản","Trao đổi chất"],"a":"Cảm ứng với kích thích","h":"Lá khép lại ngay sau khi bị chạm vào là một phản ứng.","e":"Lá cây xấu hổ khép lại khi bị chạm là phản ứng của cây trước kích thích tiếp xúc, tức là biểu hiện của tính cảm ứng ở thực vật.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Sinh trưởng ở sinh vật là:","o":["Sự biến đổi về cấu tạo và chức năng của các cơ quan","Sự tăng lên về kích thước và khối lượng của cơ thể","Sự hình thành các cá thể mới từ cơ thể bố mẹ","Sự phản ứng với các kích thích từ môi trường"],"a":"Sự tăng lên về kích thước và khối lượng của cơ thể","h":"Hãy nghĩ đến một cây con lớn dần thành cây trưởng thành.","e":"Sinh trưởng là quá trình cơ thể sinh vật tăng lên về kích thước và khối lượng nhờ sự tăng số lượng và kích thước tế bào.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Phát triển ở sinh vật là quá trình:","o":["Chỉ tăng lên về kích thước và khối lượng của cơ thể","Tạo ra các cá thể mới giống cơ thể bố mẹ","Biến đổi về cấu tạo và chức năng của tế bào, mô, cơ quan và cơ thể, diễn ra cùng với sinh trưởng","Lấy các chất dinh dưỡng từ môi trường vào cơ thể"],"a":"Biến đổi về cấu tạo và chức năng của tế bào, mô, cơ quan và cơ thể, diễn ra cùng với sinh trưởng","h":"Ví dụ: mầm cây không chỉ to lên mà còn ra lá, ra hoa.","e":"Phát triển là quá trình biến đổi về cấu tạo và chức năng của tế bào, mô, cơ quan và cơ thể; nó diễn ra đồng thời và gắn liền với sinh trưởng.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Nông dân trồng cây sắn (khoai mì) và cây mía bằng cách cắm một đoạn thân xuống đất để đoạn thân mọc thành cây mới. Hình thức sinh sản này thuộc loại:","o":["Sinh sản hữu tính","Sinh sản nhờ thụ phấn và thụ tinh","Sinh sản chỉ có ở động vật","Sinh sản vô tính"],"a":"Sinh sản vô tính","h":"Cây mới mọc lên từ một phần của cây mẹ, không qua hoa và hạt.","e":"Cây mới được tạo thành từ một phần của cơ thể mẹ (đoạn thân) mà không có sự kết hợp của giao tử nên đây là sinh sản vô tính (sinh sản sinh dưỡng).","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Vi khuẩn sinh sản chủ yếu bằng cách phân đôi: một tế bào mẹ tách thành hai tế bào con giống hệt nhau và không có sự kết hợp của giao tử. Đây là hình thức:","o":["Sinh sản vô tính","Sinh sản hữu tính","Thụ tinh ngoài","Sinh sản bằng hoa"],"a":"Sinh sản vô tính","h":"Hãy căn cứ vào đặc điểm: có hay không có sự kết hợp của giao tử.","e":"Vì quá trình phân đôi không có sự kết hợp giữa giao tử đực và giao tử cái nên sinh sản của vi khuẩn là sinh sản vô tính.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Đặc điểm cơ bản của sinh sản hữu tính là:","o":["Cơ thể mới được tạo thành từ một đoạn thân hoặc lá của cơ thể mẹ","Có sự kết hợp giữa giao tử đực và giao tử cái tạo thành hợp tử, từ đó phát triển thành cơ thể mới","Chỉ cần một cá thể duy nhất cũng tạo được cơ thể mới giống hệt mình","Cơ thể mới nảy mầm trực tiếp từ hạt phấn bay trong gió"],"a":"Có sự kết hợp giữa giao tử đực và giao tử cái tạo thành hợp tử, từ đó phát triển thành cơ thể mới","h":"Từ khoá cần chú ý là giao tử và hợp tử.","e":"Sinh sản hữu tính có sự kết hợp giữa giao tử đực và giao tử cái tạo thành hợp tử; hợp tử phát triển thành cơ thể mới mang đặc điểm của cả bố và mẹ.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nước có vai trò quan trọng nào đối với cây trồng?","o":["Cung cấp năng lượng trực tiếp cho cây hoạt động","Thay thế hoàn toàn được muối khoáng trong đất","Vừa là nguyên liệu cho quang hợp, vừa giúp hoà tan và vận chuyển các chất trong cây","Giúp cây tự tạo ra ánh sáng để quang hợp"],"a":"Vừa là nguyên liệu cho quang hợp, vừa giúp hoà tan và vận chuyển các chất trong cây","h":"Cây bị héo khi thiếu nước vì nhiều hoạt động sống bị ảnh hưởng.","e":"Nước là nguyên liệu của quang hợp, là dung môi hoà tan muối khoáng và giúp vận chuyển các chất trong cây, đồng thời giữ cho cây luôn tươi tốt.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Vì sao cây trồng cần được cung cấp muối khoáng (qua đất và phân bón)?","o":["Muối khoáng là nguồn năng lượng chính mà cây hấp thụ để sống","Muối khoáng giúp lá cây tự phát ra ánh sáng vào ban đêm","Cây không hấp thụ muối khoáng, bón phân chỉ để làm đất tơi xốp","Muối khoáng chứa các nguyên tố dinh dưỡng cần thiết như đạm, lân, kali giúp cây sinh trưởng và phát triển tốt"],"a":"Muối khoáng chứa các nguyên tố dinh dưỡng cần thiết như đạm, lân, kali giúp cây sinh trưởng và phát triển tốt","h":"Đất trồng lâu ngày bị bạc màu nên người nông dân phải bón phân.","e":"Muối khoáng (đạm, lân, kali...) là nguồn nguyên tố dinh dưỡng thiết yếu; cây hấp thụ muối khoáng hoà tan trong nước để sinh trưởng và phát triển.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Hiện tượng nào sau đây là biến đổi hoá học?","o":["Dây sắt để lâu ngoài trời bị gỉ, tạo thành lớp gỉ màu nâu đỏ","Nước đá tan chảy thành nước lỏng","Cồn trong lọ mở nắp bị bay hơi dần","Hoà tan đường vào nước được nước đường"],"a":"Dây sắt để lâu ngoài trời bị gỉ, tạo thành lớp gỉ màu nâu đỏ","h":"Hãy tìm hiện tượng có tạo thành chất mới.","e":"Sắt bị gỉ là do sắt tác dụng với oxygen và hơi nước tạo thành chất mới (gỉ sắt) nên là biến đổi hoá học; các hiện tượng còn lại chỉ thay đổi trạng thái hoặc hoà tan, không tạo chất mới.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cho một mẩu kẽm vào ống nghiệm đựng dung dịch acid, thấy có nhiều bọt khí thoát ra. Hiện tượng sủi bọt khí chứng tỏ điều gì?","o":["Kẽm đang tan chảy vì acid quá nóng","Đã xảy ra phản ứng hoá học và có chất khí mới được tạo thành","Acid trong ống nghiệm đang sôi","Kẽm chỉ bị hoà tan vật lí, không có chất mới sinh ra"],"a":"Đã xảy ra phản ứng hoá học và có chất khí mới được tạo thành","h":"Bọt khí xuất phát từ một chất không hề có sẵn trong ống nghiệm ban đầu.","e":"Khí thoát ra là chất mới sinh ra trong phản ứng giữa kẽm và acid, nên sủi bọt khí là một dấu hiệu của phản ứng hoá học.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trộn hai dung dịch trong suốt lại với nhau, sau một lúc thấy xuất hiện chất rắn không tan lắng xuống đáy ống nghiệm. Dấu hiệu này cho biết:","o":["Hai dung dịch chưa được khuấy đều với nhau","Dung dịch đã bị nhiễm bẩn từ trước","Đã xảy ra phản ứng hoá học tạo thành chất mới không tan (kết tủa)","Chất rắn tan trong dung dịch bị đông lại vì lạnh"],"a":"Đã xảy ra phản ứng hoá học tạo thành chất mới không tan (kết tủa)","h":"Chất rắn đó không hề có trong hai dung dịch ban đầu.","e":"Chất kết tủa là chất mới được tạo thành sau khi trộn hai dung dịch, chứng tỏ đã xảy ra phản ứng hoá học.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Dấu hiệu nào sau đây KHÔNG phải là dấu hiệu cho thấy có phản ứng hoá học xảy ra?","o":["Xuất hiện chất rắn kết tủa","Có khí thoát ra, dung dịch sủi bọt","Dung dịch thay đổi màu sắc và toả nhiệt","Miếng bơ tan chảy khi để ở nhiệt độ phòng"],"a":"Miếng bơ tan chảy khi để ở nhiệt độ phòng","h":"Hãy xét xem hiện tượng nào không tạo ra chất mới.","e":"Bơ tan chảy chỉ là sự thay đổi trạng thái (biến đổi vật lí), không tạo chất mới; các dấu hiệu còn lại đều thường gắn với phản ứng hoá học.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Theo định luật bảo toàn khối lượng, trong một phản ứng hoá học:","o":["Tổng khối lượng của các chất tham gia bằng tổng khối lượng của các chất sản phẩm","Tổng khối lượng các chất sản phẩm luôn lớn hơn các chất tham gia","Khối lượng của từng chất riêng lẻ đều không thay đổi","Tổng số nguyên tử của các chất sản phẩm luôn nhỏ hơn các chất tham gia"],"a":"Tổng khối lượng của các chất tham gia bằng tổng khối lượng của các chất sản phẩm","h":"Trong phản ứng hoá học, các nguyên tử chỉ sắp xếp lại chứ không mất đi.","e":"Định luật bảo toàn khối lượng: tổng khối lượng các chất tham gia phản ứng bằng tổng khối lượng các chất sản phẩm.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Đốt cháy hoàn toàn 12 g carbon trong một bình kín chứa 32 g khí oxygen, phản ứng tạo thành khí carbon dioxide. Khối lượng khí carbon dioxide thu được là:","o":["20 g","44 g","32 g","384 g"],"a":"44 g","h":"Áp dụng định luật bảo toàn khối lượng cho phản ứng xảy ra trong bình kín.","e":"Theo định luật bảo toàn khối lượng: m(CO2) = m(C) + m(O2) = 12 + 32 = 44 g.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Cho phương trình hoá học: 2H2 + O2 → 2H2O. Tỉ lệ số phân tử của H2 : O2 : H2O trong phản ứng là:","o":["1 : 1 : 1","2 : 2 : 1","2 : 1 : 2","1 : 2 : 2"],"a":"2 : 1 : 2","h":"Đọc các hệ số đứng trước công thức của từng chất trong phương trình.","e":"Các hệ số trong phương trình lần lượt là 2, 1 (hệ số 1 thường không viết) và 2, nên tỉ lệ số phân tử H2 : O2 : H2O = 2 : 1 : 2.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Phương trình hoá học nào sau đây được cân bằng đúng?","o":["Mg + O2 → MgO","Mg + O2 → 2MgO","2Mg + 2O2 → 2MgO","2Mg + O2 → 2MgO"],"a":"2Mg + O2 → 2MgO","h":"Đếm số nguyên tử của mỗi nguyên tố ở hai vế của từng phương trình.","e":"Ở phương trình 2Mg + O2 → 2MgO, mỗi vế đều có 2 nguyên tử Mg và 2 nguyên tử O nên phương trình đã cân bằng; các phương trình còn lại đều lệch số nguyên tử ở hai vế.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Một mol của bất kì chất nào (nguyên tử, phân tử hay ion) đều chứa số hạt là:","o":["6,022 × 10^23 hạt","6,022 × 10^22 hạt","6,022 × 10^24 hạt","1,0 × 10^23 hạt"],"a":"6,022 × 10^23 hạt","h":"Con số này mang tên nhà khoa học Avogadro.","e":"Theo định nghĩa, 1 mol chất chứa 6,022 × 10^23 hạt vi mô; con số này gọi là số Avogadro.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khối lượng mol của nước (H2O) là bao nhiêu? Biết khối lượng nguyên tử của H là 1 amu và của O là 16 amu.","o":["17 g/mol","18 g/mol","20 g/mol","34 g/mol"],"a":"18 g/mol","h":"Phân tử nước gồm 2 nguyên tử H và 1 nguyên tử O.","e":"M(H2O) = 2 × 1 + 16 = 18 g/mol.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Số mol của 36 g nước (H2O, có khối lượng mol M = 18 g/mol) là:","o":["0,5 mol","1 mol","2 mol","3 mol"],"a":"2 mol","h":"Dùng công thức tính số mol: n = m/M.","e":"n = m/M = 36/18 = 2 mol.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Khi hoà tan muối ăn vào nước, ta được dung dịch nước muối. Trong dung dịch này:","o":["Muối ăn là dung môi, nước là chất tan","Muối ăn và nước đều là chất tan","Nước là chất tan, muối ăn là dung môi","Muối ăn là chất tan, nước là dung môi"],"a":"Muối ăn là chất tan, nước là dung môi","h":"Chất bị hoà tan vào chất kia được gọi là chất tan.","e":"Chất tan là chất bị hoà tan (muối ăn), dung môi là chất dùng để hoà tan chất khác (nước); hỗn hợp đồng nhất thu được gọi là dung dịch.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hoà tan hoàn toàn 20 g muối ăn vào 180 g nước, thu được dung dịch muối có nồng độ phần trăm là:","o":["10%","20%","11,1%","9%"],"a":"10%","h":"Khối lượng dung dịch bằng khối lượng chất tan cộng với khối lượng dung môi.","e":"Khối lượng dung dịch = 20 + 180 = 200 g; C% = (20/200) × 100% = 10%.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Nhỏ dung dịch nước vôi trong (một base) lên giấy quỳ tím, quỳ tím sẽ:","o":["Chuyển sang màu đỏ","Chuyển sang màu xanh","Không đổi màu","Bị mất màu hoàn toàn"],"a":"Chuyển sang màu xanh","h":"Acid và base làm quỳ tím đổi màu ngược nhau.","e":"Dung dịch base làm quỳ tím hoá xanh; ngược lại, dung dịch acid làm quỳ tím hoá đỏ.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Giấm ăn có pH khoảng 3. Điều này cho biết giấm ăn:","o":["Có tính base","Là dung dịch trung tính","Có tính acid","Không phải là dung dịch"],"a":"Có tính acid","h":"So sánh giá trị pH của giấm ăn với mốc pH = 7.","e":"Thang pH chạy từ 0 đến 14: pH < 7 thì dung dịch có tính acid, pH = 7 trung tính, pH > 7 có tính base. Giấm ăn có pH = 3 < 7 nên có tính acid.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Chất nào sau đây thuộc loại muối?","o":["CO2","HCl","NaOH","NaCl"],"a":"NaCl","h":"Muối thường gồm nguyên tử kim loại liên kết với gốc acid.","e":"NaCl (natri clorua) là muối; CO2 là oxide, HCl là acid và NaOH là base.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khối lượng riêng của một chất được đo bằng đơn vị nào sau đây?","o":["kg/m³ hoặc g/cm³","kg","m³","N/m²"],"a":"kg/m³ hoặc g/cm³","h":"Khối lượng riêng là khối lượng của một đơn vị thể tích chất đó.","e":"Khối lượng riêng D = m/V nên đơn vị của nó là đơn vị khối lượng chia cho đơn vị thể tích, ví dụ kg/m³ hay g/cm³.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Một khối kim loại có khối lượng 540 g và thể tích 200 cm³. Khối lượng riêng của kim loại đó là:","o":["0,37 g/cm³","2,7 g/cm³","27 g/cm³","108 000 g/cm³"],"a":"2,7 g/cm³","h":"Dùng công thức khối lượng riêng: D = m/V.","e":"D = m/V = 540/200 = 2,7 g/cm³.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Để tăng áp suất do một vật rắn tác dụng lên mặt bị ép, người ta cần:","o":["Tăng diện tích bị ép và giảm áp lực","Giảm áp lực tác dụng lên mặt bị ép","Tăng áp lực hoặc giảm diện tích bị ép","Tăng áp lực và diện tích bị ép theo cùng một tỉ lệ"],"a":"Tăng áp lực hoặc giảm diện tích bị ép","h":"Áp suất phụ thuộc vào áp lực và diện tích bị ép theo công thức p = F/S.","e":"Áp suất p = F/S nên tăng khi áp lực F tăng hoặc diện tích bị ép S giảm; ví dụ lưỡi dao được mài mỏng (diện tích bị ép nhỏ) để cắt dễ hơn.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Một thợ lặn xuống càng sâu trong nước thì áp suất của nước tác dụng lên người thợ lặn sẽ:","o":["Giảm dần","Không thay đổi","Lúc tăng lúc giảm","Càng lớn (tăng dần)"],"a":"Càng lớn (tăng dần)","h":"Áp suất chất lỏng phụ thuộc vào độ sâu của điểm đang xét.","e":"Trong cùng một chất lỏng, điểm càng sâu thì áp suất chất lỏng tác dụng càng lớn; vì thế thợ lặn càng xuống sâu càng chịu áp suất nước lớn.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Áp suất khí quyển tồn tại là do:","o":["Lớp không khí bao quanh Trái Đất có trọng lượng, ép lên mọi vật trên mặt đất","Gió thổi mạnh trên bề mặt Trái Đất","Mặt Trời chiếu sáng làm không khí nóng lên","Trái Đất tự quay quanh trục của nó"],"a":"Lớp không khí bao quanh Trái Đất có trọng lượng, ép lên mọi vật trên mặt đất","h":"Không khí tuy rất nhẹ nhưng vẫn có khối lượng và chịu tác dụng của trọng lực.","e":"Lớp khí quyển dày hàng nghìn kilômét có trọng lượng rất lớn, tạo ra áp suất khí quyển tác dụng lên mọi vật trên Trái Đất.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Dòng điện là:","o":["Dòng các điện tích đứng yên trong dây dẫn","Dòng các điện tích dịch chuyển có hướng","Dòng nước chảy trong ống dẫn điện","Sự dịch chuyển hỗn loạn, không theo hướng nào của các điện tích"],"a":"Dòng các điện tích dịch chuyển có hướng","h":"Chú ý hai ý then chốt: điện tích và sự dịch chuyển có hướng.","e":"Dòng điện là dòng dịch chuyển có hướng của các điện tích; trong dây dẫn kim loại, đó là các electron tự do dịch chuyển có hướng.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Một mạch điện đơn giản để thắp sáng một bóng đèn cần gồm các bộ phận thiết yếu nào?","o":["Nguồn điện, bóng đèn và ampe kế","Bóng đèn, dây dẫn và vôn kế","Nguồn điện, dây dẫn, bóng đèn và khoá điện","Nguồn điện, bóng đèn và cầu chì"],"a":"Nguồn điện, dây dẫn, bóng đèn và khoá điện","h":"Mạch phải tạo thành một vòng kín và có thiết bị để đóng, ngắt mạch.","e":"Mạch điện đơn giản gồm nguồn điện (cung cấp năng lượng), dây dẫn (nối các bộ phận), bóng đèn (thiết bị tiêu thụ điện) và khoá điện (đóng/ngắt mạch).","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Vật liệu nào sau đây dẫn điện?","o":["Thanh nhựa","Thước gỗ khô","Dây cao su","Dây đồng"],"a":"Dây đồng","h":"Các kim loại thường là vật liệu dẫn điện tốt.","e":"Đồng là kim loại nên dẫn điện tốt; nhựa, gỗ khô và cao su là các vật liệu cách điện.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong công nghiệp, người ta mạ một lớp đồng lên bề mặt một vật bằng sắt bằng cách cho dòng điện chạy qua dung dịch muối đồng. Ứng dụng này dựa trên tác dụng nào của dòng điện?","o":["Tác dụng hoá học","Tác dụng nhiệt","Tác dụng phát sáng","Tác dụng sinh lí"],"a":"Tác dụng hoá học","h":"Dòng điện đã làm biến đổi chất trong dung dịch, tạo ra lớp chất mới bám lên vật.","e":"Dòng điện chạy qua dung dịch muối đồng làm đồng tách ra và bám lên vật cần mạ; đó là tác dụng hoá học của dòng điện, được ứng dụng trong kĩ thuật mạ điện.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Khi đun một ấm nước, nước ở đáy ấm nóng lên, nhẹ đi và nổi lên trên, còn nước lạnh ở phía trên chìm xuống. Sự truyền nhiệt trong nước chủ yếu theo hình thức nào?","o":["Dẫn nhiệt","Đối lưu","Bức xạ nhiệt","Bay hơi"],"a":"Đối lưu","h":"Hình thức truyền nhiệt này gắn với sự chuyển động của dòng chất lỏng hoặc chất khí.","e":"Sự truyền nhiệt bằng các dòng chất lỏng (hoặc chất khí) chuyển động gọi là đối lưu; đây là hình thức truyền nhiệt chủ yếu trong chất lỏng và chất khí.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Nồi, xoong nấu ăn thường được làm bằng kim loại, nhưng quai cầm lại làm bằng nhựa hoặc gỗ. Cách làm này dựa trên tính chất nào?","o":["Kim loại nhẹ hơn nhựa nên nồi dễ cầm hơn","Nhựa và gỗ có giá thành rẻ hơn kim loại","Kim loại dẫn nhiệt tốt giúp nấu nhanh chín, còn nhựa và gỗ dẫn nhiệt kém giúp cầm không bị bỏng","Kim loại bền hơn nên được dùng làm phần chứa thức ăn"],"a":"Kim loại dẫn nhiệt tốt giúp nấu nhanh chín, còn nhựa và gỗ dẫn nhiệt kém giúp cầm không bị bỏng","h":"Hãy xét khả năng dẫn nhiệt của hai nhóm vật liệu được dùng.","e":"Thân nồi bằng kim loại dẫn nhiệt tốt nên nhiệt truyền nhanh vào thức ăn; quai nồi bằng nhựa hoặc gỗ dẫn nhiệt kém (cách nhiệt) nên người cầm không bị nóng tay.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Để giữ cho nước đá trong thùng lâu tan vào ngày nắng nóng, người ta thường dùng thùng xốp. Lí do chính là:","o":["Xốp có màu trắng nên phản xạ ánh sáng tốt hơn","Xốp nhẹ nên dễ di chuyển","Xốp rẻ tiền và dễ mua","Xốp dẫn nhiệt rất kém nên hạn chế được nhiệt từ bên ngoài truyền vào trong thùng"],"a":"Xốp dẫn nhiệt rất kém nên hạn chế được nhiệt từ bên ngoài truyền vào trong thùng","h":"Hãy nghĩ về khả năng truyền nhiệt của vật liệu làm thùng.","e":"Xốp là chất dẫn nhiệt kém (cách nhiệt tốt), làm chậm sự truyền nhiệt từ môi trường nóng bên ngoài vào nước đá, nhờ đó nước đá lâu tan hơn.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Hệ vận động của cơ thể người gồm các cơ quan nào?","o":["Xương, khớp và cơ","Tim, mạch máu và máu","Não, tuỷ sống và dây thần kinh","Phổi, khí quản và phế quản"],"a":"Xương, khớp và cơ","h":"Đây là hệ cơ quan giúp cơ thể di chuyển và vận động.","e":"Hệ vận động gồm bộ xương, các khớp nối giữa các xương và hệ cơ bám vào xương; chúng phối hợp với nhau giúp cơ thể vận động.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong hệ tuần hoàn, động mạch đảm nhiệm chức năng nào?","o":["Dẫn máu từ các cơ quan trở về tim","Dẫn máu từ tim đến các cơ quan trong cơ thể","Trao đổi chất trực tiếp với các tế bào","Lọc máu để tạo thành nước tiểu"],"a":"Dẫn máu từ tim đến các cơ quan trong cơ thể","h":"Hãy nhớ chiều đi của máu: động mạch đưa máu ra khỏi tim.","e":"Tim co bóp đẩy máu vào các động mạch để đưa máu đi nuôi cơ thể; còn tĩnh mạch dẫn máu từ các cơ quan trở về tim.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Sự trao đổi khí giữa cơ thể và môi trường trong hệ hô hấp diễn ra chủ yếu tại:","o":["Khí quản","Phế quản","Các phế nang trong phổi","Khoang mũi"],"a":"Các phế nang trong phổi","h":"Đây là các túi khí rất nhỏ, xung quanh có mạng mao mạch dày đặc.","e":"Phế nang có thành mỏng và được bao quanh bởi mạng mao mạch dày đặc, là nơi oxygen khuếch tán vào máu và carbon dioxide từ máu đi ra ngoài.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong hệ tiêu hoá, sau khi thức ăn được biến đổi, các chất dinh dưỡng được hấp thụ vào máu chủ yếu ở:","o":["Dạ dày","Thực quản","Ruột già","Ruột non"],"a":"Ruột non","h":"Cơ quan này rất dài, có nhiều nếp gấp và lông ruột làm tăng diện tích hấp thụ.","e":"Ruột non là nơi hoàn tất quá trình tiêu hoá và hấp thụ phần lớn chất dinh dưỡng vào máu nhờ diện tích bề mặt hấp thụ rất lớn.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cơ quan nào của hệ bài tiết lọc máu để tạo thành nước tiểu?","o":["Thận","Bóng đái (bàng quang)","Ống dẫn nước tiểu","Gan"],"a":"Thận","h":"Nước tiểu được tạo ra ở cơ quan này rồi mới theo ống dẫn xuống bóng đái.","e":"Thận lọc các chất cặn bã và nước thừa trong máu để tạo thành nước tiểu; bóng đái chỉ là nơi chứa nước tiểu trước khi thải ra ngoài.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hệ thần kinh của người gồm các bộ phận chính nào?","o":["Chỉ gồm não và tuỷ sống","Não, tuỷ sống và các dây thần kinh","Não và các giác quan","Tuỷ sống và các cơ"],"a":"Não, tuỷ sống và các dây thần kinh","h":"Ngoài bộ phận trung ương còn có hệ thống dây dẫn truyền tín hiệu đi khắp cơ thể.","e":"Hệ thần kinh gồm não và tuỷ sống (trung ương thần kinh) cùng hệ thống dây thần kinh toả đi khắp cơ thể, giúp điều khiển và phối hợp mọi hoạt động sống.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Bệnh đái tháo đường thường liên quan đến hormone insulin. Insulin do cơ quan nào tiết ra?","o":["Tuyến giáp ở cổ","Gan","Tuyến tuỵ","Thận"],"a":"Tuyến tuỵ","h":"Cơ quan này vừa tiết dịch tiêu hoá, vừa tiết hormone trực tiếp vào máu.","e":"Tuyến tuỵ tiết hormone insulin giúp điều hoà lượng đường trong máu; khi cơ thể thiếu insulin hoặc insulin hoạt động kém, đường huyết tăng cao gây bệnh đái tháo đường.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Tập hợp các cá thể cùng loài, cùng sống trong một khu vực nhất định, ở một thời điểm nhất định và có khả năng sinh sản với nhau được gọi là:","o":["Quần xã sinh vật","Hệ sinh thái","Một loài sinh vật","Quần thể sinh vật"],"a":"Quần thể sinh vật","h":"Chú ý hai điều kiện: cùng loài và cùng sống trong một khu vực.","e":"Quần thể sinh vật là tập hợp các cá thể cùng loài sống trong cùng một khu vực nhất định; còn quần xã gồm nhiều quần thể thuộc các loài khác nhau.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong một khu rừng, cùng sinh sống có các quần thể thông, sồi, chim sẻ, sóc, nấm và nhiều loài khác, chúng tác động qua lại với nhau. Tập hợp tất cả các quần thể sinh vật đó được gọi là:","o":["Quần xã sinh vật","Quần thể sinh vật","Chuỗi thức ăn","Một hệ cơ quan"],"a":"Quần xã sinh vật","h":"Khi có nhiều quần thể của nhiều loài khác nhau cùng chung sống, ta dùng một khái niệm rộng hơn quần thể.","e":"Quần xã sinh vật là tập hợp nhiều quần thể thuộc các loài khác nhau cùng sống trong một khu vực và có mối quan hệ tác động qua lại với nhau.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Một hệ sinh thái hoàn chỉnh bao gồm hai thành phần là:","o":["Chỉ gồm các sinh vật sống trong khu vực","Quần xã sinh vật và môi trường sống của chúng (các yếu tố vô sinh)","Chỉ gồm các yếu tố vô sinh như đất, nước, ánh sáng","Sinh vật sản xuất và sinh vật phân giải"],"a":"Quần xã sinh vật và môi trường sống của chúng (các yếu tố vô sinh)","h":"Hệ sinh thái là khái niệm rộng hơn quần xã vì còn tính thêm một thành phần nữa.","e":"Hệ sinh thái gồm quần xã sinh vật và môi trường sống của chúng (đất, nước, không khí, ánh sáng...) luôn tác động qua lại lẫn nhau.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cho chuỗi thức ăn: Cỏ → Châu chấu → Ếch → Rắn. Trong chuỗi này, châu chấu đóng vai trò là:","o":["Sinh vật sản xuất","Sinh vật phân giải","Sinh vật tiêu thụ","Sinh vật tự dưỡng"],"a":"Sinh vật tiêu thụ","h":"Châu chấu không tự tạo ra chất hữu cơ mà ăn trực tiếp sinh vật đứng đầu chuỗi.","e":"Cỏ là sinh vật sản xuất; châu chấu ăn cỏ nên là sinh vật tiêu thụ (bậc 1), ếch là sinh vật tiêu thụ bậc 2 và rắn là sinh vật tiêu thụ bậc 3.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Hành động nào sau đây góp phần bảo vệ đa dạng sinh học và môi trường sống của sinh vật?","o":["Săn bắt các loài động vật quý hiếm để buôn bán","Chặt phá rừng đầu nguồn để lấy đất canh tác","Xả chất thải chưa qua xử lí ra sông, hồ","Trồng rừng, bảo vệ rừng và xây dựng các khu bảo tồn thiên nhiên"],"a":"Trồng rừng, bảo vệ rừng và xây dựng các khu bảo tồn thiên nhiên","h":"Hãy chọn hành động giúp các loài sinh vật giữ được nơi sống của chúng.","e":"Trồng và bảo vệ rừng, xây dựng khu bảo tồn thiên nhiên giúp gìn giữ môi trường sống, bảo vệ các loài sinh vật khỏi nguy cơ suy giảm và tuyệt chủng, tức là bảo vệ đa dạng sinh học.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Tính chất vật lí nào sau đây là tính chất chung của hầu hết các kim loại?","o":["Dẫn điện và dẫn nhiệt tốt","Dễ tan trong nước","Có màu đen sẫm","Nhẹ hơn nước và nổi trên mặt nước"],"a":"Dẫn điện và dẫn nhiệt tốt","h":"Hãy nhớ vì sao dây điện và nồi nấu thường làm bằng kim loại.","e":"Kim loại nói chung đều dẫn điện, dẫn nhiệt tốt, có ánh kim và tính dẻo; đây là các tính chất vật lí chung của kim loại.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Nhờ tính chất nào mà nhôm có thể được dát mỏng thành lá nhôm bọc thực phẩm hoặc kéo thành sợi?","o":["Tính cứng","Tính dẻo","Tính giòn","Tính nhiễm từ"],"a":"Tính dẻo","h":"Tính chất này cho phép kim loại bị kéo giãn, dát mỏng mà không vỡ.","e":"Kim loại có tính dẻo nên có thể kéo sợi, dát mỏng; nhôm dát mỏng được dùng làm lá bọc thực phẩm, giấy bạc.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi đốt cháy sắt trong khí oxygen, sản phẩm tạo thành thuộc loại chất nào?","o":["Muối sắt","Khí hydrogen","Oxide của sắt","Acid"],"a":"Oxide của sắt","h":"Kim loại tác dụng với oxygen thường tạo thành hợp chất của kim loại với oxygen.","e":"Kim loại tác dụng với oxygen tạo thành oxide; sắt cháy trong oxygen tạo oxide sắt từ (Fe3O4).","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Cho kẽm (Zn) tác dụng với dung dịch hydrochloric acid (HCl) loãng, khí thoát ra là khí nào?","o":["Oxygen","Carbon dioxide","Nitrogen","Hydrogen"],"a":"Hydrogen","h":"Nhiều kim loại tác dụng với dung dịch acid sẽ giải phóng một khí nhẹ, cháy được trong không khí.","e":"Kim loại đứng trước hydrogen trong dãy hoạt động (như Zn) tác dụng với dung dịch acid tạo thành muối và giải phóng khí hydrogen.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Để sử dụng bếp gas trong gia đình an toàn và tiết kiệm, việc làm nào sau đây là đúng?","o":["Đảm bảo gas cháy hoàn toàn với ngọn lửa xanh, thông gió tốt và khoá van bình gas sau khi nấu","Để bếp gas cháy liên tục cả ngày cho ấm nhà","Dùng xăng thay cho gas khi hết gas","Đậy kín hết cửa khi đun nấu để giữ nhiệt"],"a":"Đảm bảo gas cháy hoàn toàn với ngọn lửa xanh, thông gió tốt và khoá van bình gas sau khi nấu","h":"Hãy nghĩ đến điều kiện để nhiên liệu cháy hoàn toàn và nguy cơ rò rỉ khí gas.","e":"Nhiên liệu cháy hoàn toàn khi có đủ oxygen cho nhiệt lượng cao và ít khí độc; khoá van sau khi dùng và giữ thông gió giúp tránh rò rỉ, ngộ độc khí gas.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Trong dãy hoạt động hoá học của kim loại, kim loại nào sau đây hoạt động hoá học mạnh nhất?","o":["Sắt (Fe)","Kẽm (Zn)","Kali (K)","Đồng (Cu)"],"a":"Kali (K)","h":"Dãy hoạt động bắt đầu bằng các kim loại kiềm phản ứng rất mạnh với nước.","e":"Đầu dãy hoạt động hoá học là K, Na, Ca... nên kali là kim loại hoạt động mạnh nhất trong các kim loại đã cho.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Dãy kim loại nào sau đây được sắp xếp theo chiều hoạt động hoá học GIẢM dần?","o":["Cu, Fe, Zn, Mg, K","K, Mg, Zn, Fe, Cu","Fe, Cu, Zn, K, Mg","Zn, K, Fe, Mg, Cu"],"a":"K, Mg, Zn, Fe, Cu","h":"Hãy nhớ thứ tự đầu dãy: K, Na, Ca, Mg, Al, Zn, Fe... và Cu đứng gần cuối dãy.","e":"Theo dãy hoạt động hoá học, hoạt động giảm dần theo thứ tự K > Mg > Zn > Fe > Cu nên chỉ dãy này sắp xếp đúng.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Vì sao đồng (Cu) không tác dụng với dung dịch acid loãng để giải phóng khí hydrogen?","o":["Vì đồng không dẫn điện","Vì đồng là kim loại cứng nhất","Vì đồng tan hoàn toàn trong nước","Vì đồng đứng sau hydrogen trong dãy hoạt động hoá học của kim loại"],"a":"Vì đồng đứng sau hydrogen trong dãy hoạt động hoá học của kim loại","h":"Chỉ những kim loại đứng ở vị trí nhất định so với hydrogen mới đẩy được hydrogen ra khỏi dung dịch acid.","e":"Kim loại đứng sau hydrogen trong dãy hoạt động (như Cu, Ag) không đẩy được hydrogen ra khỏi dung dịch acid loãng nên không giải phóng khí H2.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Nhôm nhẹ và khá bền trong không khí, được dùng làm vỏ máy bay và đồ gia dụng, chủ yếu là nhờ:","o":["Nhôm là kim loại cứng nhất","Nhôm không dẫn nhiệt","Nhôm rẻ hơn mọi kim loại khác","Lớp màng oxide mỏng, bền bao phủ bề mặt bảo vệ nhôm bên trong"],"a":"Lớp màng oxide mỏng, bền bao phủ bề mặt bảo vệ nhôm bên trong","h":"Bề mặt nhôm luôn có một lớp chất mỏng sinh ra khi nhôm gặp không khí.","e":"Nhôm phản ứng với oxygen tạo lớp aluminium oxide mỏng, bền, bám chắc, ngăn nhôm bên trong bị ăn mòn tiếp, đồng thời nhôm nhẹ nên hợp làm vỏ máy bay.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"So với gang, thép có ưu điểm nổi bật nào?","o":["Mềm và dẻo hơn gang rất nhiều","Giòn hơn gang","Cứng và có tính đàn hồi tốt hơn gang","Không bị gỉ trong mọi môi trường"],"a":"Cứng và có tính đàn hồi tốt hơn gang","h":"Gang chứa nhiều carbon hơn nên giòn; thép được luyện lại để cải thiện tính chất.","e":"Thép có hàm lượng carbon thấp hơn gang nên cứng và đàn hồi tốt hơn, được dùng làm khung nhà, cầu, dao kéo; gang giòn hơn nên hay dùng đúc chi tiết.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Gang và thép đều là hợp kim của sắt với nguyên tố nào là chủ yếu?","o":["Oxygen","Carbon","Lưu huỳnh (sulfur)","Nitơ (nitrogen)"],"a":"Carbon","h":"Nguyên tố này cũng là thành phần của than đá, than chì.","e":"Gang và thép là hợp kim của sắt với carbon (kèm một số nguyên tố khác); tỉ lệ carbon quyết định tính chất của từng loại.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Kim cương rất cứng còn than chì lại mềm, dù cả hai đều cấu tạo từ nguyên tố carbon. Kim cương và than chì được gọi là gì của carbon?","o":["Các dạng thù hình","Các đồng vị","Các oxide","Các muối carbonate"],"a":"Các dạng thù hình","h":"Cùng một nguyên tố nhưng tồn tại ở nhiều dạng đơn chất khác nhau với tính chất khác nhau.","e":"Một nguyên tố có thể tồn tại ở nhiều dạng đơn chất khác nhau gọi là các dạng thù hình; carbon có các dạng thù hình như kim cương, than chì, than vô định hình.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Hợp chất nào sau đây là hợp chất hữu cơ?","o":["Carbon dioxide (CO2)","Methane (CH4)","Calcium carbonate (CaCO3)","Carbon monoxide (CO)"],"a":"Methane (CH4)","h":"Hãy nhớ các ngoại lệ: một số hợp chất chứa carbon như CO, CO2, muối carbonate không thuộc hợp chất hữu cơ.","e":"Hợp chất hữu cơ là hợp chất của carbon, trừ một số ngoại lệ như CO, CO2, muối carbonate, carbide; CH4 là hợp chất hữu cơ đơn giản nhất.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Methane (CH4) là thành phần chính của loại khí nào?","o":["Không khí","Khí oxygen nguyên chất","Khí nitrogen","Khí thiên nhiên (và khí biogas)"],"a":"Khí thiên nhiên (và khí biogas)","h":"Loại khí này được khai thác từ mỏ khí và cũng sinh ra khi ủ phân, rác hữu cơ.","e":"Khí thiên nhiên và khí biogas đều chứa chủ yếu methane (CH4), là nhiên liệu cháy toả nhiều nhiệt.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Động năng của một vật phụ thuộc vào những yếu tố nào?","o":["Khối lượng và tốc độ của vật","Chỉ phụ thuộc vào độ cao của vật","Màu sắc của vật","Nhiệt độ của vật"],"a":"Khối lượng và tốc độ của vật","h":"Vật càng nặng và chuyển động càng nhanh thì khi va chạm càng mạnh.","e":"Động năng của vật phụ thuộc vào khối lượng và tốc độ: vật có khối lượng càng lớn, chuyển động càng nhanh thì động năng càng lớn.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Hai ô tô có cùng khối lượng. Ô tô A chạy với tốc độ gấp đôi ô tô B. So sánh động năng của hai xe, ta có:","o":["Động năng của hai xe bằng nhau","Động năng của xe A nhỏ hơn động năng của xe B","Động năng của xe A lớn hơn động năng của xe B","Xe B không có động năng"],"a":"Động năng của xe A lớn hơn động năng của xe B","h":"Tốc độ tăng thì động năng tăng theo.","e":"Động năng phụ thuộc vào tốc độ nên xe chạy nhanh hơn (gấp đôi tốc độ) có động năng lớn hơn; chính xác thì động năng tăng gấp bốn lần.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Thế năng trọng trường của một vật càng lớn khi:","o":["Vật càng nhẹ và ở càng thấp","Vật chuyển động càng chậm","Vật có khối lượng càng lớn và được đặt ở vị trí càng cao","Vật có màu càng sáng"],"a":"Vật có khối lượng càng lớn và được đặt ở vị trí càng cao","h":"Hãy liên hệ với quả nặng của búa máy đóng cọc: nâng càng cao, đóng càng mạnh.","e":"Thế năng trọng trường phụ thuộc vào khối lượng của vật và độ cao của vật so với mốc tính thế năng; vật càng nặng, ở càng cao thì thế năng càng lớn.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Công cơ học chỉ được sinh ra khi nào?","o":["Khi có lực tác dụng lên vật và vật chuyển dời theo phương của lực","Chỉ cần có lực tác dụng, vật không cần chuyển động","Khi vật chuyển động đều mà không có lực nào tác dụng","Bất cứ khi nào ta chạm vào vật"],"a":"Khi có lực tác dụng lên vật và vật chuyển dời theo phương của lực","h":"Một người cố đẩy chiếc tủ nặng nhưng tủ không nhúc nhích thì có sinh công không?","e":"Công cơ học chỉ sinh ra khi lực tác dụng làm vật chuyển dời theo phương của lực; đẩy tủ mà tủ không chuyển động thì không sinh công cơ học.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Muốn nam châm điện hút được nhiều đinh sắt hơn, ta có thể làm gì?","o":["Giảm cường độ dòng điện xuống mức nhỏ nhất","Tháo bỏ lõi sắt non trong cuộn dây","Ngắt dòng điện khỏi cuộn dây","Tăng cường độ dòng điện qua cuộn dây hoặc tăng số vòng dây của cuộn dây"],"a":"Tăng cường độ dòng điện qua cuộn dây hoặc tăng số vòng dây của cuộn dây","h":"Lực hút của nam châm điện gắn liền với dòng điện chạy trong cuộn dây quấn quanh lõi sắt.","e":"Nam châm điện mạnh lên khi cường độ dòng điện lớn hơn hoặc số vòng dây nhiều hơn (và có lõi sắt non); ngắt điện thì nam châm điện mất từ tính.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Dòng điện cảm ứng xuất hiện trong một cuộn dây dẫn kín khi nào?","o":["Khi cuộn dây và nam châm cùng đứng yên","Khi số đường sức từ xuyên qua cuộn dây biến thiên (thay đổi theo thời gian)","Khi cuộn dây được hở mạch","Khi không có từ trường xung quanh cuộn dây"],"a":"Khi số đường sức từ xuyên qua cuộn dây biến thiên (thay đổi theo thời gian)","h":"Thí nghiệm đưa nam châm lại gần hoặc ra xa cuộn dây nối với điện kế cho thấy kim điện kế lệch.","e":"Hiện tượng cảm ứng điện từ: khi số đường sức từ qua cuộn dây kín biến thiên thì trong cuộn dây xuất hiện dòng điện cảm ứng.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Dòng điện xoay chiều khác dòng điện một chiều ở điểm cơ bản nào?","o":["Dòng điện xoay chiều không có cường độ","Dòng điện xoay chiều chỉ có trong pin","Dòng điện một chiều luân phiên đổi chiều liên tục","Dòng điện xoay chiều luân phiên đổi chiều, còn dòng điện một chiều không đổi chiều"],"a":"Dòng điện xoay chiều luân phiên đổi chiều, còn dòng điện một chiều không đổi chiều","h":"Điện lấy từ ổ cắm trong nhà thuộc loại nào và chiều của nó có thay đổi không?","e":"Dòng điện xoay chiều luân phiên đổi chiều theo thời gian (điện lưới sinh hoạt), còn dòng điện một chiều (từ pin, acquy) luôn giữ một chiều.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Máy phát điện xoay chiều ở nhà máy điện hoạt động dựa trên hiện tượng vật lí nào?","o":["Hiện tượng khúc xạ ánh sáng","Hiện tượng cảm ứng điện từ","Sự dẫn nhiệt của kim loại","Sự nhiễm điện do cọ xát"],"a":"Hiện tượng cảm ứng điện từ","h":"Bên trong máy phát điện có cuộn dây quay trong từ trường của nam châm.","e":"Máy phát điện xoay chiều biến cơ năng thành điện năng dựa trên hiện tượng cảm ứng điện từ: quay cuộn dây (hoặc nam châm) làm số đường sức từ qua cuộn dây biến thiên, sinh ra dòng điện xoay chiều.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Hiện tượng khúc xạ ánh sáng là hiện tượng:","o":["Tia sáng bị hắt trở lại môi trường cũ","Tia sáng bị môi trường hấp thụ hoàn toàn","Tia sáng bị gãy khúc tại mặt phân cách khi truyền từ môi trường trong suốt này sang môi trường trong suốt khác","Tia sáng tự đổi màu khi truyền đi"],"a":"Tia sáng bị gãy khúc tại mặt phân cách khi truyền từ môi trường trong suốt này sang môi trường trong suốt khác","h":"Hiện tượng này khiến chiếc đũa trong cốc nước trông như bị gãy ở mặt nước.","e":"Khi ánh sáng truyền qua mặt phân cách giữa hai môi trường trong suốt khác nhau (ví dụ không khí – nước), tia sáng bị gãy khúc tại mặt phân cách, gọi là hiện tượng khúc xạ ánh sáng.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Đặc điểm nào sau đây đúng với thấu kính hội tụ?","o":["Phần rìa mỏng hơn phần giữa và làm chùm tia sáng song song tới hội tụ tại một điểm","Phần giữa mỏng hơn phần rìa","Làm chùm tia sáng song song phân kì ra xa nhau","Chỉ có tác dụng như một tấm kính phẳng"],"a":"Phần rìa mỏng hơn phần giữa và làm chùm tia sáng song song tới hội tụ tại một điểm","h":"Kính lúp dùng để phóng to ảnh là một thấu kính hội tụ.","e":"Thấu kính hội tụ có phần rìa mỏng hơn phần giữa; chùm tia tới song song đi qua thấu kính sẽ hội tụ tại tiêu điểm, nên được dùng làm kính lúp, vật kính máy ảnh.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Nguồn năng lượng nào sau đây là năng lượng tái tạo?","o":["Năng lượng mặt trời","Than đá","Dầu mỏ","Khí đốt tự nhiên"],"a":"Năng lượng mặt trời","h":"Nguồn năng lượng tái tạo được bổ sung liên tục trong tự nhiên và khó cạn kiệt.","e":"Năng lượng mặt trời (cũng như gió, nước, địa nhiệt) là năng lượng tái tạo; than đá, dầu mỏ, khí đốt là nhiên liệu hoá thạch không tái tạo và sẽ cạn dần.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Vì sao mỗi người cần sử dụng năng lượng một cách tiết kiệm và hiệu quả?","o":["Vì năng lượng không cần thiết cho đời sống","Vì dùng nhiều điện sẽ làm hỏng mọi thiết bị ngay lập tức","Vì năng lượng tái tạo là nguồn gây ô nhiễm chính","Vì nhiên liệu hoá thạch có hạn và gây ô nhiễm môi trường; tiết kiệm năng lượng giúp giảm chi phí và bảo vệ môi trường"],"a":"Vì nhiên liệu hoá thạch có hạn và gây ô nhiễm môi trường; tiết kiệm năng lượng giúp giảm chi phí và bảo vệ môi trường","h":"Hãy nghĩ đến nguồn than, dầu đang cạn dần và khí thải khi đốt nhiên liệu.","e":"Sử dụng năng lượng tiết kiệm, hiệu quả giúp kéo dài nguồn nhiên liệu hoá thạch đang cạn kiệt, giảm phát thải khí nhà kính, bảo vệ môi trường và giảm chi phí cho gia đình, xã hội.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Vật chất di truyền ở cấp độ phân tử, lưu giữ thông tin quy định các tính trạng của cơ thể, là chất nào?","o":["Protein","Lipid (chất béo)","DNA","Tinh bột"],"a":"DNA","h":"Tên viết tắt này gồm ba chữ cái bắt đầu bằng D và nằm chủ yếu trong nhân tế bào.","e":"DNA là vật chất di truyền ở cấp độ phân tử, lưu giữ và truyền đạt thông tin di truyền qua các thế hệ tế bào và cơ thể.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Phân tử DNA có cấu trúc như thế nào?","o":["Gồm một mạch thẳng từ các amino acid","Gồm hai mạch xoắn kép, cấu tạo từ các đơn phân là nucleotide","Có dạng hình cầu rỗng","Gồm các đơn phân là glucose xếp thành vòng"],"a":"Gồm hai mạch xoắn kép, cấu tạo từ các đơn phân là nucleotide","h":"Hãy nhớ hình ảnh chiếc thang xoắn thường thấy trong sách sinh học.","e":"DNA cấu tạo từ các đơn phân nucleotide, gồm hai mạch polynucleotide xoắn kép ngược chiều, liên kết với nhau theo nguyên tắc bổ sung.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Gene được hiểu là:","o":["Toàn bộ tế bào","Một đoạn của phân tử DNA quy định một tính trạng nhất định của cơ thể","Một loại protein trong máu","Một cơ quan trong cơ thể"],"a":"Một đoạn của phân tử DNA quy định một tính trạng nhất định của cơ thể","h":"Mỗi tính trạng như màu mắt, nhóm máu... đều liên quan đến đơn vị di truyền này nằm trên DNA.","e":"Gene là một đoạn của phân tử DNA, mang thông tin quy định một tính trạng (hoặc cấu tạo một sản phẩm) nhất định của cơ thể.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong tế bào thường (tế bào sinh dưỡng) của người có bao nhiêu nhiễm sắc thể?","o":["46 nhiễm sắc thể (23 cặp)","23 nhiễm sắc thể","92 nhiễm sắc thể","44 nhiễm sắc thể"],"a":"46 nhiễm sắc thể (23 cặp)","h":"Số này là một số chẵn, gồm các cặp nhiễm sắc thể tương đồng.","e":"Tế bào sinh dưỡng của người có bộ nhiễm sắc thể lưỡng bội 2n = 46, gồm 23 cặp; còn giao tử chỉ có n = 23 nhiễm sắc thể.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Ứng dụng nào sau đây là ứng dụng của công nghệ gene?","o":["Lai hai giống lúa thuần chủng theo cách truyền thống","Ghép cành cam lên gốc bưởi","Chọn lọc cây tốt để làm giống qua nhiều vụ","Tạo giống cây trồng biến đổi gene cho năng suất cao, kháng sâu bệnh"],"a":"Tạo giống cây trồng biến đổi gene cho năng suất cao, kháng sâu bệnh","h":"Công nghệ này can thiệp trực tiếp vào vật chất di truyền của sinh vật.","e":"Công nghệ gene chuyển gene mong muốn vào sinh vật để tạo sinh vật biến đổi gene, ứng dụng trong nông nghiệp (cây kháng sâu, năng suất cao) và y học (sản xuất insulin).","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Kết quả của quá trình nguyên phân từ một tế bào mẹ là:","o":["Bốn tế bào con có bộ nhiễm sắc thể giảm một nửa","Một tế bào con duy nhất","Hai tế bào con có bộ nhiễm sắc thể giống hệt tế bào mẹ","Hai tế bào con có số nhiễm sắc thể gấp đôi tế bào mẹ"],"a":"Hai tế bào con có bộ nhiễm sắc thể giống hệt tế bào mẹ","h":"Nguyên phân giúp cơ thể lớn lên và thay thế tế bào già, chết nên bộ gene phải được giữ nguyên.","e":"Nguyên phân tạo ra 2 tế bào con có bộ nhiễm sắc thể giống hệt nhau và giống tế bào mẹ, giúp cơ thể sinh trưởng và tái tạo mô.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Quá trình giảm phân tạo ra các tế bào con có đặc điểm nào?","o":["Hai tế bào con giống hệt tế bào mẹ","Bốn tế bào con có bộ nhiễm sắc thể gấp đôi tế bào mẹ","Bốn tế bào con, mỗi tế bào có bộ nhiễm sắc thể giảm đi một nửa so với tế bào mẹ","Một tế bào con có đầy đủ bộ nhiễm sắc thể của mẹ"],"a":"Bốn tế bào con, mỗi tế bào có bộ nhiễm sắc thể giảm đi một nửa so với tế bào mẹ","h":"Giảm phân xảy ra khi hình thành giao tử để chuẩn bị cho thụ tinh.","e":"Giảm phân qua hai lần phân bào liên tiếp tạo 4 tế bào con có bộ nhiễm sắc thể đơn bội (n), bằng một nửa tế bào mẹ, làm tiền đề cho thụ tinh khôi phục bộ 2n ở hợp tử.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Loại tế bào nào sau đây ở người được tạo thành nhờ quá trình giảm phân?","o":["Tế bào da","Tế bào cơ tim","Tế bào thần kinh","Tế bào sinh dục (giao tử: tinh trùng và trứng)"],"a":"Tế bào sinh dục (giao tử: tinh trùng và trứng)","h":"Các tế bào này chỉ chứa một nửa số nhiễm sắc thể so với tế bào thường.","e":"Giảm phân xảy ra ở cơ quan sinh dục, tạo giao tử (tinh trùng, trứng) mang bộ nhiễm sắc thể đơn bội n = 23 ở người.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Biến dị là hiện tượng:","o":["Con sinh ra giống hệt bố mẹ về mọi tính trạng","Con sinh ra có những điểm khác biệt so với bố mẹ và so với nhau","Tế bào phân chia liên tục không ngừng","Sinh vật tăng kích thước theo thời gian"],"a":"Con sinh ra có những điểm khác biệt so với bố mẹ và so với nhau","h":"Nhờ hiện tượng này mà anh chị em ruột vẫn có nhiều nét khác nhau.","e":"Biến dị là những khác biệt về tính trạng giữa các cá thể con với bố mẹ và giữa các cá thể với nhau, tạo nên sự đa dạng của sinh giới.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Đột biến được hiểu là:","o":["Những biến đổi xảy ra trong vật chất di truyền (gene hoặc nhiễm sắc thể)","Sự thay đổi của môi trường sống quanh sinh vật","Sự tăng cơ bắp do luyện tập thể thao","Sự đổi màu da khi phơi nắng lâu ngày"],"a":"Những biến đổi xảy ra trong vật chất di truyền (gene hoặc nhiễm sắc thể)","h":"Loại biến đổi này có thể di truyền cho thế hệ sau vì liên quan đến bộ gene.","e":"Đột biến là những biến đổi trong vật chất di truyền ở cấp phân tử (gene) hoặc cấp tế bào (nhiễm sắc thể); đột biến có thể có hại, có lợi hoặc trung tính.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Bệnh Đao (hội chứng Down) ở người là do nguyên nhân nào?","o":["Tế bào của người bệnh thừa 1 nhiễm sắc thể ở cặp số 21 (có 3 nhiễm sắc thể số 21)","Tế bào thiếu hẳn cặp nhiễm sắc thể số 21","Nhiễm một loại vi khuẩn gây bệnh","Thiếu vitamin trong khẩu phần ăn"],"a":"Tế bào của người bệnh thừa 1 nhiễm sắc thể ở cặp số 21 (có 3 nhiễm sắc thể số 21)","h":"Đây là bệnh di truyền liên quan đến số lượng nhiễm sắc thể, không phải do nhiễm trùng hay dinh dưỡng.","e":"Bệnh Đao là đột biến số lượng nhiễm sắc thể: người bệnh có 47 nhiễm sắc thể do thừa 1 chiếc ở cặp 21, gây chậm phát triển trí tuệ và một số dị tật bẩm sinh.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Vì sao hôn nhân giữa những người có quan hệ huyết thống gần (cận huyết) làm tăng nguy cơ bệnh di truyền ở con?","o":["Vì con của họ luôn có thêm nhiễm sắc thể","Vì bố mẹ gần huyết thống dễ mang cùng gene lặn gây bệnh, khi kết hợp ở con sẽ biểu hiện thành bệnh","Vì máu của bố mẹ giống nhau nên con yếu hơn","Vì họ thường sống chung một môi trường ô nhiễm"],"a":"Vì bố mẹ gần huyết thống dễ mang cùng gene lặn gây bệnh, khi kết hợp ở con sẽ biểu hiện thành bệnh","h":"Nhiều gene gây bệnh là gene lặn, chỉ biểu hiện khi có mặt cả hai bản sao từ bố và mẹ.","e":"Người cùng huyết thống có hệ gene giống nhau nhiều, dễ cùng mang gene lặn có hại; con nhận cả hai gene lặn từ bố và mẹ sẽ mắc bệnh di truyền, nên pháp luật cấm kết hôn cận huyết.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Theo học thuyết tiến hoá của Đac-uyn, chọn lọc tự nhiên diễn ra như thế nào?","o":["Mọi cá thể trong quần thể đều sống sót và sinh sản như nhau","Sinh vật tự thay đổi cơ thể theo ý muốn để thích nghi","Con người chọn những cá thể tốt nhất để nhân giống","Các cá thể có đặc điểm thích nghi tốt hơn với môi trường sẽ sống sót và sinh sản nhiều hơn, truyền lại đặc điểm đó cho đời sau"],"a":"Các cá thể có đặc điểm thích nghi tốt hơn với môi trường sẽ sống sót và sinh sản nhiều hơn, truyền lại đặc điểm đó cho đời sau","h":"Đac-uyn quan sát thấy số con sinh ra nhiều hơn số con sống sót đến tuổi sinh sản rất nhiều.","e":"Chọn lọc tự nhiên: trong cuộc đấu tranh sinh tồn, cá thể mang đặc điểm thích nghi tốt hơn có khả năng sống sót và sinh sản cao hơn, qua nhiều thế hệ quần thể dần thích nghi với môi trường.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Bằng chứng nào sau đây là bằng chứng trực tiếp, quan trọng về lịch sử tiến hoá của sinh giới?","o":["Truyện cổ tích về nguồn gốc loài người","Ý kiến chủ quan của một cá nhân","Hoá thạch của các sinh vật cổ được lưu giữ trong các lớp đất đá","Bức ảnh chụp một loài vật hiện nay"],"a":"Hoá thạch của các sinh vật cổ được lưu giữ trong các lớp đất đá","h":"Loại bằng chứng này cho thấy hình ảnh thật của sinh vật từng sống trong quá khứ xa xưa.","e":"Hoá thạch là di tích của sinh vật cổ được bảo tồn trong đất đá, là bằng chứng trực tiếp ghi lại quá trình tiến hoá; ngoài ra còn có bằng chứng so sánh cấu tạo cơ quan giữa các loài.","t":"khtn-lop9","g":9,"l":"nhe-nhang"}];